from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

app = FastAPI()

class Model(BaseModel):
    param: str = Field(validation_alias="param_validation_alias")

@app.get("/query")
async def query_model(data: Model = Query()):
    return {"param": data.param}

def test_query_model_with_validation_alias():
    client = TestClient(app)
    response = client.get("/query", params={"param_validation_alias": "value"})
    assert response.status_code == 200, response.text
    assert response.json() == {"param": "value"}

def test_query_model_with_validation_alias_by_name():
    client = TestClient(app)
    response = client.get("/query", params={"param": "value"})
    assert response.status_code == 422, response.text

def test_query_model_with_both_alias_and_validation_alias():
    class ModelBoth(BaseModel):
        param: str = Field(alias="param_alias", validation_alias="param_validation_alias")

    @app.get("/query_both")
    async def query_model_both(data: ModelBoth = Query()):
        return {"param": data.param}

    client = TestClient(app)
    response = client.get("/query_both", params={"param_validation_alias": "value"})
    assert response.status_code == 200, response.text
    assert response.json() == {"param": "value"}

    response = client.get("/query_both", params={"param_alias": "value"})
    assert response.status_code == 422, response.text
